CREATE OR REPLACE FUNCTION solver_private.build_snapshot_payload_before_b4f169(p_run_id uuid, p_month date, p_matrix_version_id uuid, p_scenario_id uuid, p_scope_type text, p_scope_role_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_snapshot jsonb;
