declare
  v_result jsonb:='{}'::jsonb;
  v_value jsonb;
begin
  if p_values is null then return v_result; end if;
  foreach v_value in array p_values loop
    v_result:=solver_private.jsonb_deep_merge_v2(v_result,v_value);
  end loop;
